sparql:
SELECT ?p ?title (COUNT(DISTINCT ?museum) AS ?museums) WHERE {
  ?r owl:sameAs wd:Q5598 .
  ?p a mc:Print ; mc:artist ?r .
  OPTIONAL { ?p dcterms:title ?title }
  ?w mc:impressionOf ?p ; mc:museum ?museum .
} GROUP BY ?p ?title
HAVING (COUNT(DISTINCT ?museum) = 4)
ORDER BY ?title

SELECT ?museum (COUNT(DISTINCT ?w) AS ?impressions) WHERE {
  ?r owl:sameAs wd:Q5598 .
  ?p a mc:Print ; mc:artist ?r .
  OPTIONAL { ?p dcterms:title ?t }
  OPTIONAL { ?p mc:bartsch ?b }
  FILTER(CONTAINS(LCASE(STR(?t)), "hundred guilder") || ?b = 74)
  ?w mc:impressionOf ?p ; mc:museum ?museum .
} GROUP BY ?museum ORDER BY DESC(?impressions)

SELECT ?museum (COUNT(DISTINCT ?w) AS ?n) WHERE {
  ?r owl:sameAs wd:Q5598 .
  ?w mc:artist ?r ; mc:objectType "painting" ; mc:museum ?museum .
} GROUP BY ?museum ORDER BY DESC(?n)

SELECT ?decade (COUNT(DISTINCT ?w) AS ?n) WHERE {
  ?r owl:sameAs wd:Q5598 .
  ?w mc:artist ?r ; mc:objectType "print" ; mc:beginYear ?y .
  BIND(FLOOR(?y / 10) * 10 AS ?decade)
} GROUP BY ?decade ORDER BY DESC(?n)

SELECT (COUNT(?p) AS ?n) WHERE {
  {
    SELECT ?p WHERE {
      ?r owl:sameAs wd:Q5598 .
      ?p a mc:Print ; mc:artist ?r .
      ?w mc:impressionOf ?p ; mc:museum ?m .
    }
    GROUP BY ?p
    HAVING (COUNT(DISTINCT ?m) = 1)
  }
}
